import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Which datapoints does an ESPHome light have?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/03.referenz/03.licht.md"},"headers":[],"relativePath":"adapter/esphome/referenz/licht.md","filePath":"adapter/esphome/referenz/licht.md","lastUpdated":null}'),s={name:"adapter/esphome/referenz/licht.md"};function h(d,e,n,l,r,c){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="which-datapoints-does-an-esphome-light-have" tabindex="-1">Which datapoints does an ESPHome light have? <a class="header-anchor" href="#which-datapoints-does-an-esphome-light-have" aria-label="Permalink to &quot;Which datapoints does an ESPHome light have?&quot;">​</a></h1><p><a id="datapoints-rgb-rgbw-lamp-have"></a></p><h2 id="which-datapoints-does-an-rgb-rgbw-lamp-have-and-which-values-does-it-expect" tabindex="-1">Which datapoints does an RGB/RGBW lamp have and which values does it expect? <a class="header-anchor" href="#which-datapoints-does-an-rgb-rgbw-lamp-have-and-which-values-does-it-expect" aria-label="Permalink to &quot;Which datapoints does an RGB/RGBW lamp have and which values does it expect?&quot;">​</a></h2><p>A light has one state each under <code>esphome.0.&lt;device&gt;.Light.&lt;key&gt;</code> for on/off, brightness, color channels, color temperature, effect and hex color. Write brightness and color channels as a number from 0 to 255, the hex color as <code>#rrggbb</code>.</p><h3 id="the-states" tabindex="-1">The states <a class="header-anchor" href="#the-states" aria-label="Permalink to &quot;The states&quot;">​</a></h3><p>Only the values the light reports exist. A plain on/off light therefore has fewer states than an RGBW light.</p><table tabindex="0"><thead><tr><th>State</th><th>Values</th><th>Meaning</th></tr></thead><tbody><tr><td><code>state</code></td><td><code>true</code> / <code>false</code></td><td>on or off</td></tr><tr><td><code>brightness</code></td><td>0 to 255</td><td>overall brightness</td></tr><tr><td><code>red</code>, <code>green</code>, <code>blue</code></td><td>0 to 255 each</td><td>color channels</td></tr><tr><td><code>white</code></td><td>0 to 255</td><td>white channel, RGBW only</td></tr><tr><td><code>colorBrightness</code></td><td>0 to 255</td><td>brightness of the color part</td></tr><tr><td><code>coldWhite</code>, <code>warmWhite</code></td><td>0 to 255 each</td><td>cold and warm white</td></tr><tr><td><code>colorHEX</code></td><td>e.g. <code>#ff6600</code> or <code>#f60</code></td><td>color as hex value, only for lights with red, green and blue</td></tr><tr><td><code>colorTemperature</code></td><td>number</td><td>color temperature on the same 0 to 255 scale as brightness, not in Kelvin or mired</td></tr><tr><td><code>colorMode</code></td><td>number</td><td>ESPHome color mode, e.g. <code>35</code> for RGB</td></tr><tr><td><code>effect</code></td><td>text</td><td>name of the light effect from the YAML</td></tr><tr><td><code>transitionLength</code></td><td>milliseconds</td><td>transition time, sent with every command</td></tr><tr><td><code>config.rgbAutoWhite</code></td><td><code>true</code> / <code>false</code></td><td>RGBW only: <code>#ffffff</code> switches to the white channel</td></tr></tbody></table><p>An invalid hex value is dropped without a message, the light stays as it is.</p><h3 id="how-to-switch-a-light" tabindex="-1">How to switch a light <a class="header-anchor" href="#how-to-switch-a-light" aria-label="Permalink to &quot;How to switch a light&quot;">​</a></h3><ol><li>In admin, open the &quot;Objects&quot; tab and go to <code>esphome.0.&lt;device&gt;.Light.&lt;key&gt;</code>.</li><li>Write a state, e.g. <code>brightness</code> to <code>128</code> or <code>colorHEX</code> to <code>#ff6600</code>.</li><li>The adapter sends a complete light command. When the light reports its new state, the value is confirmed (<code>ack = true</code>).</li></ol><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;device&gt;.Light.&lt;key&gt;.state&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;device&gt;.Light.&lt;key&gt;.colorHEX&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#ff6600&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The command always contains on/off, transition time and the last known values, but only those the light supports according to its color modes. An effect is only sent when <code>effect</code> is not empty.</p><p><strong>See also:</strong> <a href="#transition-length-flash-length-light">Transition length and flash length</a> · <a href="#select-light-effect-iobroker">Selecting a light effect</a> · <a href="./../anleitungen/automatisieren#use-white-channel-rgbw-lamp">Using the white channel automatically</a> · <a href="./datenpunkte#command-acknowledged-ack-happens-offline">When a command counts as confirmed</a></p><p><a id="transition-length-flash-length-light"></a></p><h2 id="how-do-i-set-transition-length-and-flash-length-of-a-light" tabindex="-1">How do I set transition length and flash length of a light? <a class="header-anchor" href="#how-do-i-set-transition-length-and-flash-length-of-a-light" aria-label="Permalink to &quot;How do I set transition length and flash length of a light?&quot;">​</a></h2><p>You set the transition in the state <code>esphome.0.&lt;device&gt;.Light.&lt;key&gt;.transitionLength</code>, in milliseconds. The default is <code>0</code>. It exists for lights with brightness or colour.</p><p>The value is sent with every light command until you change it, also after a restart. If you only write <code>transitionLength</code>, the adapter sends a light command with the current values.</p><p>The adapter offers no flash length. If you need blinking, add an effect in the YAML, e.g. <code>strobe</code>, and choose it via <code>effect</code>.</p><p><strong>See also:</strong> <a href="#select-light-effect-iobroker">Choose a light effect</a></p><p><a id="select-light-effect-iobroker"></a></p><h2 id="how-do-i-select-a-light-effect-from-iobroker" tabindex="-1">How do I select a light effect from ioBroker? <a class="header-anchor" href="#how-do-i-select-a-light-effect-from-iobroker" aria-label="Permalink to &quot;How do I select a light effect from ioBroker?&quot;">​</a></h2><p>Write the name of the effect into <code>esphome.0.&lt;device&gt;.Light.&lt;key&gt;.effect</code>, exactly as it is written in the YAML under <code>effects:</code>. The adapter sends it with the next light command.</p><p>There is no drop-down list. You see the effects the light knows in the YAML or, with configuration states switched on, in its <code>config</code> folder. The adapter does not send an empty value. To end the effect, write <code>None</code>.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;device&gt;.Light.&lt;key&gt;.effect&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Rainbow&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><strong>See also:</strong> <a href="#datapoints-rgb-rgbw-lamp-have">States of a light</a></p>`,25)])])}const f=t(s,[["render",h]]);export{g as __pageData,f as default};
